            "ALTER TABLE subscriptions ADD COLUMN trial_to_active_date TEXT"
        )
        connection.execute(
            "UPDATE subscriptions SET trial_to_active_date = start_date"
            " WHERE trial_to_active_date IS NULL"
        )
    connection.commit()


