def trial_info(customer_id: str, plan: str) -> int:
    """Print the compact trial status of one subscription."""
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    connection = _connect()
    try:
